/**
 * PaginatedReportModal — Power BI Paginated Report UI
 *
 * Architecture:
 * - "Add to Report" stores the FULL graphDefinition (not a screenshot)
 * - Each visual has a per-visual config panel (ReportVisualConfigPanel)
 * - PDF is generated by POST /api/reports/generate-visual-pdf
 *   → Backend re-renders charts from data (no DOM capture at all)
 */

import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  X, FileText, Download, Table, BarChart2, LineChart, PieChart,
  Trash2, Plus, CheckCircle2, Settings2,
} from 'lucide-react';
import ReportVisualConfigPanel from './ReportVisualConfigPanel';
import './PaginatedReportModal.css';
import './ReportVisualConfigPanel.css';

// ─── Default config factory ───────────────────────────────────────────────────
const DEFAULT_REPORT_CONFIG = {
  mode: 'current_state', // current_state | top_n | bottom_n | custom_filter | date_range
  topN: 20,
  bottomN: 10,
  groupRemaining: true,
  sortOrder: 'desc',          // asc | desc
  pageLayout: 'full_page',     // full_page | half_page | chart_table | kpi_chart
  oneChartPerPage: true,
  includeDataTable: false,
  includeSummaryMetrics: false,
  landscapeMode: false,
  categoryThreshold: 20,
};

// ─── Helpers ─────────────────────────────────────────────────────────────────

/** Visual types that we skip entirely (cannot be meaningfully rendered) */
const SKIP_TYPES = new Set(['text', 'slicer', 'shape', 'button', 'image']);

function formatType(type) {
  return String(type || '').replace(/_/g, ' ');
}

function getGraphTitle(g) {
  return g?.options?.title || formatType(g?.graph_type) || 'Untitled';
}

function GraphIcon({ type, size = 16 }) {
  const t = (type || '').toLowerCase();
  if (t === 'table') return <Table size={size} />;
  if (t === 'line' || t === 'step' || t === 'area') return <LineChart size={size} />;
  if (t === 'pie' || t === 'donut') return <PieChart size={size} />;
  return <BarChart2 size={size} />;
}

function modeBadgeLabel(mode) {
  const map = {
    current_state: 'Current State',
    top_n: 'Top N',
    bottom_n: 'Bottom N',
    date_range: 'Date Range',
    custom_filter: 'Custom Filter',
  };
  return map[mode] || 'Current State';
}

// ─── Component ────────────────────────────────────────────────────────────────

const PaginatedReportModal = ({
  isOpen,
  onClose,
  fileId,
  dataset,
  fileName,
  reportElements = [],
  onReportElementsChange,
  availableGraphs = [],
  measures = [],
}) => {
  const validFileId = fileId || dataset?.metadata?.fileId;

  // ── Report-level settings ────────────────────────────────────────────────
  const [reportName, setReportName] = useState(fileName ? `${fileName} Report` : 'Paginated Report');
  const [pageSize, setPageSize] = useState('A4');
  const [orientation, setOrientation] = useState('landscape');
  const [rowsPerPage, setRowsPerPage] = useState(30);
  const [showHeader, setShowHeader] = useState(true);
  const [showFooter, setShowFooter] = useState(true);
  const [includeSummary, setIncludeSummary] = useState(true);

  // ── Queued visuals ───────────────────────────────────────────────────────
  const [localElements, setLocalElements] = useState(reportElements);
  const skipSyncRef = useRef(false);

  // ── Data table columns ────────────────────────────────────────────────────
  const [selectedColumns, setSelectedColumns] = useState([]);

  // ── Config panel ──────────────────────────────────────────────────────────
  const [configPanelTarget, setConfigPanelTarget] = useState(null); // element id

  // ── UI state ──────────────────────────────────────────────────────────────
  const [isGenerating, setIsGenerating] = useState(false);
  const [generateStatus, setGenerateStatus] = useState('');
  const [availSearch, setAvailSearch] = useState('');

  // Sync parent → local elements (skip on our own writes)
  useEffect(() => {
    if (skipSyncRef.current) { skipSyncRef.current = false; return; }
    // Migrate old elements that lack graphDefinition / reportConfig
    const migrated = reportElements.map(el => ({
      ...el,
      graphDefinition: el.graphDefinition || {},
      reportConfig: el.reportConfig || { ...DEFAULT_REPORT_CONFIG },
    }));
    setLocalElements(migrated);
  }, [reportElements]);

  // Keep selectedColumns in sync with dataset columns and measures
  const datasetColumnsKey = dataset?.columns?.map(c => c.name).join(',') ?? '';
  const measuresKey = measures?.map(m => m.name).join(',') ?? '';
  useEffect(() => {
    const dbNames = dataset?.columns ? dataset.columns.map(c => c.name) : [];
    const measureNames = measures ? measures.map(m => m.name) : [];
    setSelectedColumns([...dbNames, ...measureNames]);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [datasetColumnsKey, measuresKey]);

  // ── Element management ────────────────────────────────────────────────────

  const addGraphToReport = useCallback((graph) => {
    if (localElements.some(e => e.id === graph.id)) return;

    const rawType = (graph.graph_type || 'bar').toLowerCase();

    // ★ Snapshot the FULL graphDefinition — not an image
    const el = {
      id: graph.id,
      title: getGraphTitle(graph),
      visualType: rawType,
      dashboardId: graph.dashboardId || null,
      // Full live state from dashboard
      graphDefinition: {
        graph_type: graph.graph_type,
        x_axis: graph.x_axis,
        y_axis: graph.y_axis,
        aggregation: graph.aggregation,
        // Send both camelCase and snake_case so backend always finds it
        fileId: graph.file_id || graph.fileId || validFileId,
        file_id: graph.file_id || graph.fileId || validFileId,
        options: {
          title: graph.options?.title,
          dimension_fields: graph.options?.dimension_fields || [],
          measure_fields: graph.options?.measure_fields || [],
          filters: graph.options?.filters || [],
          drillPath: graph.options?.drillPath || [],
          drillLevelIndex: graph.options?.drillLevelIndex || 0,
          expandModeActive: graph.options?.expandModeActive || false,
          sorting: graph.options?.sorting || null,
          color_scheme: graph.options?.color_scheme || null,
        },
      },
      // Per-visual report overrides (defaults)
      reportConfig: { ...DEFAULT_REPORT_CONFIG },
    };

    skipSyncRef.current = true;
    const updated = [...localElements, el];
    setLocalElements(updated);
    onReportElementsChange?.(updated);

    // Open config panel immediately for new additions
    setConfigPanelTarget(el.id);
  }, [localElements, onReportElementsChange, validFileId]);

  const removeElement = useCallback((elementId) => {
    setLocalElements(prev => {
      const updated = prev.filter(e => e.id !== elementId);
      onReportElementsChange?.(updated);
      return updated;
    });
    if (configPanelTarget === elementId) setConfigPanelTarget(null);
  }, [onReportElementsChange, configPanelTarget]);

  const updateElementConfig = useCallback((elementId, newConfig) => {
    setLocalElements(prev => {
      const updated = prev.map(e =>
        e.id === elementId ? { ...e, reportConfig: newConfig } : e
      );
      onReportElementsChange?.(updated);
      return updated;
    });
    setConfigPanelTarget(null);
  }, [onReportElementsChange]);

  const isGraphAdded = (id) => localElements.some(e => e.id === id);
  const configElement = localElements.find(e => e.id === configPanelTarget) || null;

  const toggleColumn = (name) => setSelectedColumns(p => p.includes(name) ? p.filter(c => c !== name) : [...p, name]);
  const selectAllCols = () => {
    const dbNames = dataset?.columns ? dataset.columns.map(c => c.name) : [];
    const measureNames = measures ? measures.map(m => m.name) : [];
    setSelectedColumns([...dbNames, ...measureNames]);
  };
  const deselectAllCols = () => setSelectedColumns([]);

  // ── PDF generation ────────────────────────────────────────────────────────

  const handleGenerate = async () => {
    if (localElements.length === 0 && selectedColumns.length === 0) {
      alert('Please add visuals or select columns for the data table.');
      return;
    }

    setIsGenerating(true);
    setGenerateStatus('Preparing report…');

    try {
      // Build visual state payload — NO screenshots
      const chartVisuals = localElements.filter(el => !SKIP_TYPES.has(el.visualType));

      const requestBody = {
        title: reportName,
        page_size: pageSize,
        orientation,
        file_id: validFileId,
        include_summary: includeSummary,
        rows_per_page: rowsPerPage,
        show_header: showHeader,
        show_footer: showFooter,

        // Full visual state — backend re-renders from data
        visuals: chartVisuals.map(el => ({
          id: el.id,
          title: el.title,
          visualType: el.visualType,
          graphDefinition: el.graphDefinition || {},
          reportConfig: el.reportConfig || DEFAULT_REPORT_CONFIG,
        })),

        // Data table columns (optional)
        table_columns: selectedColumns,
      };

      setGenerateStatus(`Rendering ${chartVisuals.length} visual${chartVisuals.length !== 1 ? 's' : ''} from data…`);

      const response = await fetch('/analytics/api/reports/generate-visual-pdf', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(requestBody),
      });

      const contentType = response.headers.get('content-type') || '';
      if (!contentType.includes('application/pdf')) {
        let errMsg = 'Unknown error';
        try {
          const j = await response.json();
          errMsg = j.error || j.detail || errMsg;
        } catch { /* ignore */ }
        throw new Error('PDF generation failed: ' + errMsg);
      }

      setGenerateStatus('Downloading PDF…');
      const blob = await response.blob();
      if (blob.size < 200) throw new Error('PDF appears to be empty');

      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${reportName.replace(/\s+/g, '_')}.pdf`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      onClose();
    } catch (err) {
      console.error('[PaginatedReport] Error:', err);
      alert('Error: ' + (err.message || 'Failed to generate report'));
    } finally {
      setIsGenerating(false);
      setGenerateStatus('');
    }
  };

  // ─────────────────────────────────────────────────────────────────────────
  if (!isOpen) return null;

  const chartGraphs = (availableGraphs || []).filter(g => {
    const t = (g?.graph_type || '').toLowerCase();
    return t && !SKIP_TYPES.has(t);
  });

  const filteredGraphs = availSearch
    ? chartGraphs.filter(g =>
      getGraphTitle(g).toLowerCase().includes(availSearch.toLowerCase()) ||
      (g.graph_type || '').toLowerCase().includes(availSearch.toLowerCase())
    )
    : chartGraphs;

  const hasConfig = configPanelTarget && configElement;

  return (
    <div className="prm-overlay" onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className={`prm-modal paginated-report-modal${hasConfig ? ' has-config-panel' : ''}`}>

        {/* ── Header ── */}
        <div className="prm-header">
          <FileText size={18} className="prm-header-icon" />
          <h2>Paginated Report</h2>
          <button type="button" className="prm-close" onClick={onClose} aria-label="Close">
            <X size={18} />
          </button>
        </div>

        {/* ── Body (two-column when config panel is open) ── */}
        <div className="prm-layout">

          {/* ── Main panel ── */}
          <div className="prm-body">

            {/* Report settings — compact strip */}
            <div className="prm-section prm-section--settings">
              <div className="prm-settings-grid">
                <div className="prm-field">
                  <label className="prm-label">Title</label>
                  <input
                    type="text"
                    value={reportName}
                    onChange={e => setReportName(e.target.value)}
                    className="prm-input"
                    placeholder="Report title"
                  />
                </div>
                <div className="prm-field">
                  <label className="prm-label">Page</label>
                  <select value={pageSize} onChange={e => setPageSize(e.target.value)} className="prm-select">
                    <option value="A4">A4</option>
                    <option value="LETTER">Letter</option>
                  </select>
                </div>
                <div className="prm-field">
                  <label className="prm-label">Layout</label>
                  <select value={orientation} onChange={e => setOrientation(e.target.value)} className="prm-select">
                    <option value="landscape">Landscape</option>
                    <option value="portrait">Portrait</option>
                  </select>
                </div>
                <div className="prm-field">
                  <label className="prm-label">Rows/page</label>
                  <input
                    type="number"
                    value={rowsPerPage}
                    onChange={e => setRowsPerPage(parseInt(e.target.value, 10) || 30)}
                    min={1} max={5000}
                    className="prm-input"
                  />
                </div>
              </div>
              <div className="prm-checkbox-row">
                <label className="prm-checkbox"><input type="checkbox" checked={includeSummary} onChange={e => setIncludeSummary(e.target.checked)} /><span>Summary</span></label>
                <label className="prm-checkbox"><input type="checkbox" checked={showHeader} onChange={e => setShowHeader(e.target.checked)} /><span>Headers</span></label>
                <label className="prm-checkbox"><input type="checkbox" checked={showFooter} onChange={e => setShowFooter(e.target.checked)} /><span>Page #</span></label>
              </div>
            </div>

            <div className="prm-split">
            {/* Available visualizations */}
            {filteredGraphs.length > 0 && (
              <div className="prm-section prm-section--half">
                <div className="prm-section-header-row">
                  <h3 className="prm-section-title">
                    Visualizations
                    <span className="prm-count-chip">{chartGraphs.length}</span>
                  </h3>
                  <input
                    type="search"
                    className="prm-search"
                    placeholder="Search…"
                    value={availSearch}
                    onChange={e => setAvailSearch(e.target.value)}
                  />
                </div>
                <div className="prm-avail-list">
                  {filteredGraphs.map(g => {
                    const added = isGraphAdded(g.id);
                    const title = getGraphTitle(g);
                    const type = (g?.graph_type || '').toLowerCase();
                    return (
                      <div key={g.id} className={`prm-avail-item${added ? ' is-added' : ''}`}>
                        <GraphIcon type={type} size={14} />
                        <div className="prm-avail-body">
                          <span className="prm-avail-title">{title}</span>
                          <span className="prm-type-chip">{formatType(type)}</span>
                        </div>
                        <button
                          type="button"
                          className={`prm-add-btn${added ? ' is-added' : ''}`}
                          onClick={() => addGraphToReport(g)}
                          disabled={added}
                          title={added ? 'Already added' : 'Add to report'}
                        >
                          {added ? <CheckCircle2 size={16} /> : <Plus size={16} />}
                        </button>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

            {/* Report visual queue */}
            {localElements.length > 0 && (
              <div className="prm-section prm-section--compact">
                <h3 className="prm-section-title">
                  Queue
                  <span className="prm-count-chip">{localElements.length}</span>
                </h3>
                <div className="prm-queue-list">
                  {localElements.map((el) => {
                    const mode = el.reportConfig?.mode || 'current_state';
                    const isConfigOpen = configPanelTarget === el.id;

                    return (
                      <div key={el.id} className={`prm-queue-item${isConfigOpen ? ' config-open' : ''}`}>
                        <GraphIcon type={el.visualType} size={14} />
                        <div className="prm-queue-body">
                          <span className="prm-queue-title">{el.title || 'Untitled'}</span>
                          <span className={`prm-mode-chip mode-${mode}`}>{modeBadgeLabel(mode)}</span>
                        </div>
                        <div className="prm-queue-actions">
                          <button
                            type="button"
                            className={`prm-cfg-btn${isConfigOpen ? ' active' : ''}`}
                            onClick={() => setConfigPanelTarget(isConfigOpen ? null : el.id)}
                            title="Configure visual"
                          >
                            <Settings2 size={14} />
                          </button>
                          <button
                            type="button"
                            className="prm-remove-btn"
                            onClick={() => removeElement(el.id)}
                            title="Remove"
                          >
                            <Trash2 size={14} />
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

            {/* Data table columns */}
            <div className="prm-section prm-section--half">
              <div className="prm-section-header-row">
                <h3 className="prm-section-title">
                  Data columns
                  {selectedColumns.length > 0 && (
                    <span className="prm-count-chip">{selectedColumns.length}</span>
                  )}
                </h3>
                <div className="prm-col-actions">
                  <button type="button" onClick={selectAllCols}>All</button>
                  <button type="button" onClick={deselectAllCols}>Clear</button>
                </div>
              </div>
              <div className="prm-columns">
                {dataset?.columns || measures.length > 0 ? (
                  <>
                    {dataset?.columns && dataset.columns.map(col => (
                      <label key={col.name} className="prm-col-item">
                        <input
                          type="checkbox"
                          checked={selectedColumns.includes(col.name)}
                          onChange={() => toggleColumn(col.name)}
                        />
                        <span className="prm-col-name">{col.name}</span>
                        <span className="prm-col-type">{col.type}</span>
                      </label>
                    ))}
                    {measures.map(m => (
                      <label key={m.id || m.name} className="prm-col-item measure-col-item">
                        <input
                          type="checkbox"
                          checked={selectedColumns.includes(m.name)}
                          onChange={() => toggleColumn(m.name)}
                        />
                        <span className="prm-col-name" style={{ color: '#6366f1', fontWeight: 600 }}>{m.name} (Measure)</span>
                        <span className="prm-col-type">numeric</span>
                      </label>
                    ))}
                  </>
                ) : (
                  <div className="prm-empty-msg">No columns available</div>
                )}
              </div>
            </div>
            </div>
          </div>

          {/* ── Config panel (right side) ── */}
          {hasConfig && (
            <div className="prm-config-sidebar">
              <ReportVisualConfigPanel
                visual={configElement}
                onSave={(newConfig) => updateElementConfig(configPanelTarget, newConfig)}
                onClose={() => setConfigPanelTarget(null)}
              />
            </div>
          )}
        </div>

        {/* ── Footer ── */}
        <div className="prm-footer">
          <div className="prm-footer-info">
            {dataset?.metadata && (
              <span className="prm-info-pill">
                {(dataset.metadata.totalRows || dataset.rows?.length || 0).toLocaleString()} rows
              </span>
            )}
            <span className="prm-info-pill">{selectedColumns.length} columns</span>
            {localElements.length > 0 && (
              <span className="prm-info-pill">{localElements.length} visual{localElements.length !== 1 ? 's' : ''}</span>
            )}
            {isGenerating && generateStatus && (
              <span className="prm-info-pill prm-info-status">{generateStatus}</span>
            )}
          </div>
          <div className="prm-footer-btns">
            <button
              type="button"
              className="prm-btn prm-btn-cancel"
              onClick={onClose}
              disabled={isGenerating}
            >
              Cancel
            </button>
            <button
              type="button"
              className="prm-btn prm-btn-generate"
              onClick={handleGenerate}
              disabled={isGenerating || (selectedColumns.length === 0 && localElements.length === 0)}
            >
              {isGenerating
                ? <span className="prm-generating">{generateStatus || 'Generating…'}</span>
                : <><Download size={15} /> Generate PDF</>
              }
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PaginatedReportModal;